exercises.solution:
import * as fs from "fs";
interface Entry {
  name: string;
  amount: number;
  ok: boolean;
}
function parseEntry(line: string): Entry {
  const parts = line.split(",");
  if (parts.length !== 2) return { name: line.trim(), amount: 0, ok: false };
  const amount = Number((parts[1] ?? "").trim());
  if (Number.isNaN(amount) || amount < 0) {
    return { name: (parts[0] ?? "").trim(), amount: 0, ok: false };
  }
  return { name: (parts[0] ?? "").trim(), amount, ok: true };
}
const lines = fs.readFileSync(0, "utf8").trim().split("\n")
  .filter((l) => l.trim().length > 0);
const entries: Entry[] = lines.map((l) => parseEntry(l));
const good = entries.filter((e) => e.ok);
const total = good.reduce((sum, e) => sum + e.amount, 0);
for (const e of good) console.log(`${e.name}: $${e.amount.toFixed(2)}`);
console.log(`Accepted ${good.length}, rejected ${entries.length - good.length}, total $${total.toFixed(2)}`);

