import * as fs from "fs";
type Status = "paid" | "unpaid";
interface Expense {
  desc: string;
  amount: number;
  status: Status;
}
function parse(line: string): Expense {
  const p = line.trim().split(" ");
  return { desc: p[0] ?? "", amount: Number(p[1]), status: p[2] === "paid" ? "paid" : "unpaid" };
}
const rows: Expense[] = fs.readFileSync(0, "utf8").trim().split("\n").map(parse);
const total = rows.reduce((s, r) => s + r.amount, 0);
const paid = rows.filter((r) => r.status === "paid").reduce((s, r) => s + r.amount, 0);
const largest = rows.reduce((best, r) => (r.amount > best.amount ? r : best), rows[0]!);
console.log(`Count:   ${rows.length}`);
console.log(`Total:   $${total.toFixed(2)}`);
console.log(`Paid:    $${paid.toFixed(2)}`);
console.log(`Unpaid:  $${(total - paid).toFixed(2)}`);
console.log(`Largest: ${largest.desc}`);

