exercise.solution:
import * as fs from "fs";
class Expense {
  readonly desc: string;
  readonly cents: number;
  readonly tag: string;

  constructor(desc: string, cents: number, tag: string) {
    this.desc = desc;
    this.cents = cents;
    this.tag = tag;
  }

  static fromLine(line: string): Expense {
    const p = line.trim().split(" ");
    return new Expense(p[0] ?? "", Math.round(Number(p[1] ?? "0") * 100), p[2] ?? "");
  }

  get dollars(): string {
    return `$${(this.cents / 100).toFixed(2)}`;
  }
}
class Ledger {
  private entries: Expense[] = [];

  add(e: Expense): void {
    this.entries.push(e);
  }

  get count(): number {
    return this.entries.length;
  }

  total(): number {
    return this.entries.reduce((s, e) => s + e.cents, 0);
  }

  byTag(): Record<string, number> {
    const out: Record<string, number> = {};
    for (const e of this.entries) {
      out[e.tag] = (out[e.tag] ?? 0) + e.cents;
    }
    return out;
  }

  largest(): Expense {
    const first = this.entries[0];
    if (first === undefined) {
      throw new Error("empty ledger");
    }
    let best: Expense = first;
    for (const e of this.entries) {
      if (e.cents > best.cents) {
        best = e;
      }
    }
    return best;
  }
}
const ledger = new Ledger();
for (const line of fs.readFileSync(0, "utf8").trim().split("\n")) {
  ledger.add(Expense.fromLine(line));
}
const tags = ledger.byTag();
const parts = Object.keys(tags).sort().map((t) => `${t}=$${((tags[t] ?? 0) / 100).toFixed(2)}`);
const big = ledger.largest();
console.log(`Entries:  ${ledger.count}`);
console.log(`Total:    $${(ledger.total() / 100).toFixed(2)}`);
console.log(`By tag:   ${parts.join(", ")}`);
console.log(`Largest:  ${big.desc} ${big.dollars}`);

