import * as fs from "fs";
type Cents = number & { readonly __brand: "Cents" };
function cents(n: number): Cents {
  return n as Cents;
}
function addCents(a: Cents, b: Cents): Cents {
  return cents(a + b);
}
function money(c: Cents): string {
  return `$${(c / 100).toFixed(2)}`;
}
const CATEGORIES = ["food", "fun", "home"] as const;
type Category = (typeof CATEGORIES)[number];
const BUDGETS = {
  food: 5000,
  fun: 2000,
  home: 80000,
} satisfies Record<Category, number>;
function toCategory(s: string): Category {
  for (const c of CATEGORIES) {
    if (c === s) {
      return c;
    }
  }
  throw new Error(`unknown category: ${s}`);
}
const totals: Record<Category, Cents> = {
  food: cents(0),
  fun: cents(0),
  home: cents(0),
};
let count = 0;
let total: Cents = cents(0);
for (const line of fs.readFileSync(0, "utf8").trim().split("\n")) {
  const p = line.trim().split(" ");
  const amount = cents(Math.round(Number(p[1] ?? "0") * 100));
  const cat = toCategory(p[2] ?? "");
  totals[cat] = addCents(totals[cat], amount);
  total = addCents(total, amount);
  count = count + 1;
}
console.log(`Entries:  ${count}`);
console.log(`Total:    ${money(total)}`);
for (const c of CATEGORIES) {
  const spent = totals[c];
  const budget = cents(BUDGETS[c]);
  const status = spent > budget ? "OVER" : "ok";
  console.log(`${(c + ":").padEnd(10)}${money(spent)} of ${money(budget)} ${status}`);
}

