exercise.solution:
import * as fs from "fs";
// ---- config.ts ----
declare global {
  var BUDGET_CURRENCY: string;
}
interface Strictness {
  readonly strict: boolean;
  readonly noUncheckedIndexedAccess: boolean;
}
const PRESET = {
  strict: true,
  noUncheckedIndexedAccess: true,
} satisfies Strictness;
function label(p: Strictness): string {
  return p.noUncheckedIndexedAccess ? "strict+indexed" : "strict";
}
// ---- money.ts ----
function round2(n: number): number {
  return Math.round(n * 100) / 100;
}
function toMoney(cents: number): string {
  return `${BUDGET_CURRENCY} ${round2(cents / 100).toFixed(2)}`;
}
// ---- entry.ts ----
interface Entry {
  readonly desc: string;
  readonly cents: number;
  readonly tag: string;
}
function parseEntry(line: string): Entry | undefined {
  const parts = line.trim().split(/\s+/);
  if (parts.length !== 3) {
    return undefined;
  }
  const desc = parts[0] ?? "";
  const cents = Number(parts[1] ?? "");
  const tag = parts[2] ?? "";
  if (!Number.isFinite(cents)) {
    return undefined;
  }
  return { desc, cents, tag };
}
// ---- report.ts ----
function report(entries: readonly Entry[]): readonly string[] {
  let total = 0;
  const byTag: Record<string, number> = {};
  for (const e of entries) {
    total = total + e.cents;
    byTag[e.tag] = (byTag[e.tag] ?? 0) + e.cents;
  }
  let topTag = "none";
  let topCents = -1;
  for (const tag of Object.keys(byTag).sort()) {
    const cents = byTag[tag] ?? 0;
    if (cents > topCents) {
      topTag = tag;
      topCents = cents;
    }
  }
  return [
    `Ledger:   ${entries.length} entries (${label(PRESET)})`,
    `Total:    ${toMoney(total)}`,
    topTag === "none" ? "Top tag:  none" : `Top tag:  ${topTag} ${toMoney(topCents)}`,
  ];
}
// ---- index.ts ----
export { toMoney, parseEntry, report };
export type { Entry };
// ---- main.ts ----
globalThis.BUDGET_CURRENCY = "USD";
const lines = fs.readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
const entries: Entry[] = [];
for (const line of lines) {
  const e = parseEntry(line);
  if (e !== undefined) {
    entries.push(e);
  }
}
for (const out of report(entries)) {
  console.log(out);
}

