import * as fs from "fs";
function delay(ms: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}
const lines = fs.readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
async function loadPage(index: number, line: string): Promise<readonly number[]> {
  await delay((lines.length - index) * 8);
  if (line.trim() === "ERR") {
    throw new Error(`page ${index + 1} is unavailable`);
  }
  return line.trim().split(/\s+/).map(Number);
}
const results = await Promise.allSettled(lines.map((line, i) => loadPage(i, line)));
let entries = 0;
let okPages = 0;
let total = 0;
for (let i = 0; i < results.length; i = i + 1) {
  const r = results[i];
  if (r === undefined) {
    continue;
  }
  if (r.status === "fulfilled") {
    okPages = okPages + 1;
    entries = entries + r.value.length;
    for (const cents of r.value) {
      total = total + cents;
    }
    console.log(`Page ${i + 1}:   ok (${r.value.length} entries)`);
  } else {
    const why = r.reason instanceof Error ? r.reason.message : "unknown";
    console.log(`Page ${i + 1}:   failed (${why})`);
  }
}
console.log(`Loaded:   ${entries} entries from ${okPages} of ${results.length} pages`);
console.log(`Total:    $${(total / 100).toFixed(2)}`);

