import * as fs from "fs";
interface Entry {
  readonly desc: string;
  readonly cents: number;
}
interface Change {
  readonly kind: "add" | "remove";
  readonly entry: Entry;
}
const entries: Entry[] = [];
const undoStack: Change[] = [];
const redoStack: Change[] = [];
function total(): string {
  let cents = 0;
  for (const e of entries) {
    cents = cents + e.cents;
  }
  return `$${(cents / 100).toFixed(2)}`;
}
function apply(change: Change): void {
  if (change.kind === "add") {
    entries.push(change.entry);
  } else {
    entries.pop();
  }
}
function invert(change: Change): Change {
  return { kind: change.kind === "add" ? "remove" : "add", entry: change.entry };
}
const lines = fs.readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
for (const line of lines) {
  const parts = line.trim().split(/\s+/);
  const command = parts[0] ?? "";
  if (command === "add") {
    const desc = parts[1] ?? "";
    const cents = Number(parts[2] ?? "0");
    const change: Change = { kind: "add", entry: { desc, cents } };
    apply(change);
    undoStack.push(change);
    redoStack.length = 0;
    console.log(`add ${desc} ${cents} -> total ${total()}`);
  } else if (command === "remove") {
    const last = entries[entries.length - 1];
    if (last === undefined) {
      console.log("remove (nothing to remove)");
      continue;
    }
    const change: Change = { kind: "remove", entry: last };
    apply(change);
    undoStack.push(change);
    redoStack.length = 0;
    console.log(`remove ${last.desc} -> total ${total()}`);
  } else if (command === "undo") {
    const change = undoStack.pop();
    if (change === undefined) {
      console.log("undo (nothing to undo)");
      continue;
    }
    apply(invert(change));
    redoStack.push(change);
    console.log(`undo ${change.kind} ${change.entry.desc} -> total ${total()}`);
  } else if (command === "redo") {
    const change = redoStack.pop();
    if (change === undefined) {
      console.log("redo (nothing to redo)");
      continue;
    }
    apply(change);
    undoStack.push(change);
    console.log(`redo ${change.kind} ${change.entry.desc} -> total ${total()}`);
  }
}
console.log(`Entries:  ${entries.length}`);
console.log(`Total:    ${total()}`);
console.log(`History:  ${undoStack.length} undoable, ${redoStack.length} redoable`);

