exercises.solution:
import * as fs from "fs";
const words = fs.readFileSync(0, "utf8").trim().split(" ");
function anagrams(a: string, b: string): boolean {
  if (a.length !== b.length) {
    return false;
  }
  const counts = new Map<string, number>();
  for (const ch of a) {
    counts.set(ch, (counts.get(ch) ?? 0) + 1);
  }
  for (const ch of b) {
    const n = counts.get(ch) ?? 0;
    if (n === 0) {
      return false;
    }
    counts.set(ch, n - 1);
  }
  return true;
}
console.log(anagrams(words[0] ?? "", words[1] ?? ""));

