import * as fs from "fs";
const nums = fs.readFileSync(0, "utf8").trim().split(" ").map(Number);
function keyOf(x: number, y: number): string {
  return `${x},${y}`;
}
const visited = new Set<string>();
let revisits = 0;
for (let i = 0; i + 1 < nums.length; i = i + 2) {
  const key = keyOf(nums[i] ?? 0, nums[i + 1] ?? 0);
  if (visited.has(key)) {
    revisits = revisits + 1;
  }
  visited.add(key);
}
console.log(`${visited.size} ${revisits}`);

