exercise.solution:
import * as fs from "fs";
interface Entry {
  readonly desc: string;
  readonly cents: number;
  readonly tag: string;
}
const byTag = new Map<string, Entry[]>();
const seen = new Set<string>();
let count = 0;
const lines = fs.readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
for (const line of lines) {
  const parts = line.trim().split(/\s+/);
  if (parts.length !== 3) {
    continue;
  }
  const desc = parts[0] ?? "";
  const cents = Number(parts[1] ?? "");
  const tag = parts[2] ?? "";
  if (!Number.isFinite(cents)) {
    continue;
  }
  if (seen.has(desc)) {
    console.log(`rejected: ${desc} (duplicate)`);
    continue;
  }
  seen.add(desc);
  const group = byTag.get(tag) ?? [];
  group.push({ desc, cents, tag });
  byTag.set(tag, group);
  count = count + 1;
}
function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}
const totals = new Map<string, number>();
for (const [tag, group] of byTag) {
  let sum = 0;
  for (const e of group) {
    sum = sum + e.cents;
  }
  totals.set(tag, sum);
}
console.log(`Entries:  ${count}`);
console.log(`Tags:     ${byTag.size}`);
const tags = [...byTag.keys()].sort();
for (const tag of tags) {
  const group = byTag.get(tag) ?? [];
  const padded = String(group.length).padStart(2);
  console.log(`${tag.padEnd(9)} ${padded}  ${money(totals.get(tag) ?? 0)}`);
}
let topTag = "none";
let topCents = -1;
for (const tag of tags) {
  const sum = totals.get(tag) ?? 0;
  if (sum > topCents) {
    topTag = tag;
    topCents = sum;
  }
}
console.log(topTag === "none" ? "Top tag:  none" : `Top tag:  ${topTag} ${money(topCents)}`);
console.log(`Unique:   ${seen.size} descriptions`);

