import * as fs from "fs";
const nums = fs.readFileSync(0, "utf8").trim().split(" ").map(Number);
interface N {
  readonly value: number;
  next: N | null;
}
function build(xs: readonly number[]): N | null {
  let head: N | null = null;
  for (let i = xs.length - 1; i >= 0; i = i - 1) {
    head = { value: xs[i] ?? 0, next: head };
  }
  return head;
}
function has(head: N | null, target: number): boolean {
  let cur: N | null = head;
  while (cur !== null) {
    if (cur.value === target) {
      return true;
    }
    cur = cur.next;
  }
  return false;
}
