import * as fs from "fs";
interface Cat {
  readonly name: string;
  readonly cents: number;
  readonly budget: number;
  readonly kids: Cat[];
}
const lines = fs.readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
function parse(rows: readonly string[]): Cat | null {
  let root: Cat | null = null;
  const open: Cat[] = [];
  for (const row of rows) {
    const indent = row.length - row.trimStart().length;
    const depth = Math.floor(indent / 2);
    const parts = row.trim().split(/\s+/);
    if (parts.length !== 3) {
      continue;
    }
    const node: Cat = {
      name: parts[0] ?? "",
      cents: Number(parts[1] ?? "0"),
      budget: Number(parts[2] ?? "0"),
      kids: [],
    };
    open.length = depth;
    const parent = open[depth - 1];
    if (parent === undefined) {
      root = node;
    } else {
      parent.kids.push(node);
    }
    open.push(node);
  }
  return root;
}
function total(c: Cat): number {
  let sum = c.cents;
  for (const kid of c.kids) {
    sum = sum + total(kid);
  }
  return sum;
}
function* walk(c: Cat, depth: number): Generator<[Cat, number]> {
  yield [c, depth];
  for (const kid of c.kids) {
    yield* walk(kid, depth + 1);
  }
}
function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}
const root = parse(lines);
const over: string[] = [];
let categories = 0;
let deepest = 0;
let bigLeaf = "none";
let bigCents = -1;
if (root !== null) {
  for (const [cat, depth] of walk(root, 0)) {
    categories = categories + 1;
    deepest = Math.max(deepest, depth + 1);
    const sum = total(cat);
    const isOver = sum > cat.budget;
    if (isOver) {
      over.push(cat.name);
    }
    if (cat.kids.length === 0 && cat.cents > bigCents) {
      bigLeaf = cat.name;
      bigCents = cat.cents;
    }
    const label = `${"  ".repeat(depth)}${cat.name}`.padEnd(12);
    console.log(`${label}${money(sum).padStart(8)} / ${money(cat.budget)}${isOver ? "  OVER" : ""}`);
  }
}
console.log(`Categories:   ${categories}`);
console.log(`Deepest:      ${deepest}`);
console.log(`Over budget:  ${over.length === 0 ? "none" : over.join(", ")}`);
console.log(bigCents < 0 ? "Biggest leaf: none" : `Biggest leaf: ${bigLeaf} ${money(bigCents)}`);

