const queries = (split < 0 ? [] : all.slice(split + 1)).filter((l) => l.trim() !== "");
function parse(rows: readonly string[]): Cat | null {
  let root: Cat | null = null;
  const open: Cat[] = [];
  for (const row of rows) {
    const depth = Math.floor((row.length - row.trimStart().length) / 2);
    const parts = row.trim().split(/\s+/);
    if (parts.length < 2) {
      continue;
    }
    const node: Cat = { name: parts[0] ?? "", cents: Number(parts[1] ?? "0"), kids: [] };
    open.length = depth;
    const parent = open[depth - 1];
    if (parent === undefined) {
      root = node;
    } else {
      parent.kids.push(node);
    }
    open.push(node);
  }
  return root;
}
function total(c: Cat): number {
  let sum = c.cents;
  for (const kid of c.kids) {
    sum = sum + total(kid);
  }
  return sum;
}
let visited = 0;
function pathTo(c: Cat, name: string): readonly string[] | null {
  visited = visited + 1;
  if (c.name === name) {
    return [c.name];
  }
  for (const kid of c.kids) {
    const below = pathTo(kid, name);
    if (below !== null) {
      return [c.name, ...below];
    }
  }
  return null;
}
