import * as fs from "fs";
const n = Number(fs.readFileSync(0, "utf8").trim());
function sized(size: number): readonly number[] {
  return Array.from({ length: size }, (_, i) => i + 1);
}
function sumOps(size: number): number {
  let ops = 0;
  let total = 0;
  for (const x of sized(size)) {
    ops = ops + 1;
    total = total + x;
  }
  return ops + total * 0;
}
function binaryOps(size: number): number {
  const xs = sized(size);
  const target = size;
  let lo = 0;
  let hi = xs.length - 1;
  let ops = 0;
  while (lo <= hi) {
    ops = ops + 1;
    const mid = Math.floor((lo + hi) / 2);
    const v = xs[mid] ?? 0;
    if (v === target) {
      return ops;
    }
    if (v < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return ops;
}
function pairOps(size: number): number {
  let ops = 0;
  for (let i = 0; i < size; i = i + 1) {
    for (let j = i + 1; j < size; j = j + 1) {
      ops = ops + 1;
    }
  }
  return ops;
}
function dedupeOps(size: number): number {
  let ops = 0;
  const seen: number[] = [];
  for (const x of sized(size)) {
    ops = ops + seen.length;
    if (!seen.includes(x)) {
      seen.push(x);
    }
  }
  return ops;
}
function classify(ratio: number): string {
  if (ratio < 1.2) {
    return "O(1)";
  }
  if (ratio < 1.5) {
    return "O(log n)";
  }
  if (ratio < 2.5) {
    return "O(n)";
  }
  if (ratio < 3.5) {
    return "O(n log n)";
  }
  return "O(n^2)";
}
if (!Number.isFinite(n) || n < 2) {
  console.log("n must be at least 2");
} else {
  const algorithms: readonly [string, (size: number) => number][] = [
    ["sum", sumOps],
    ["binary", binaryOps],
    ["pairs", pairOps],
    ["dedupe", dedupeOps],
  ];
  let slowest = "none";
  let worstRatio = -1;
  for (const [name, run] of algorithms) {
    const small = run(n);
    const big = run(n * 2);
    const ratio = small === 0 ? 1 : big / small;
    if (ratio > worstRatio) {
      slowest = name;
      worstRatio = ratio;
