  let ops = 0;
  for (let i = 0; i < size; i = i + 1) {
    ops = ops + 1;
  }
  return ops;
}
function classify(ratio: number): string {
  if (ratio < 1.5) {
    return "O(log n)";
  }
  if (ratio < 2.5) {
    return "O(n)";
  }
  if (ratio < 3.5) {
    return "O(n log n)";
  }
  return "O(n^2)";
}
function report(name: string, run: (size: number) => number): void {
  const a = run(n);
  const b = run(n * 2);
  const c = run(n * 4);
  const r1 = a === 0 ? 1 : b / a;
  const r2 = b === 0 ? 1 : c / b;
  const unstable = Math.abs(r1 - r2) > 0.5;
  console.log(
    `${name.padEnd(10)}${r1.toFixed(2)} ${r2.toFixed(2)}  ${classify(r2)}` +
      `${unstable ? "  unstable" : ""}`,
  );
}
if (!Number.isFinite(n) || n < 2) {
  console.log("n must be at least 2");
} else {
  report("sum", sumOps);
  report("pairs", pairOps);
}

