import * as fs from "fs";
const lines = fs.readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
const xs: readonly number[] = (lines[0] ?? "")
  .trim()
  .split(/\s+/)
  .filter((s) => s !== "")
  .map(Number)
  .sort((a, b) => a - b);
let steps = 0;
function bound(target: number, inclusive: boolean): number {
  let lo = 0;
  let hi = xs.length;
  while (lo < hi) {
    steps = steps + 1;
    const mid = Math.floor((lo + hi) / 2);
    const v = xs[mid] ?? 0;
    if (inclusive ? v <= target : v < target) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}
function nearest(target: number): number {
  const i = bound(target, false);
  const at = i < xs.length ? xs[i] ?? 0 : Number.MAX_SAFE_INTEGER;
  const before = i > 0 ? xs[i - 1] ?? 0 : Number.MIN_SAFE_INTEGER;
  const gapAt = Math.abs(at - target);
  const gapBefore = Math.abs(target - before);
  return gapBefore <= gapAt ? before : at;
}
let queries = 0;
for (const line of lines.slice(1)) {
  const parts = line.trim().split(/\s+/);
  const kind = parts[0] ?? "";
  const a = Number(parts[1] ?? "0");
  const before = steps;
  if (kind === "?") {
    const i = bound(a, false);
    const present = i < xs.length && (xs[i] ?? 0) === a;
    queries = queries + 1;
    console.log(`?  ${a}  ${present ? `present at ${i}` : "absent"}  steps ${steps - before}`);
  } else if (kind === "+") {
    const i = bound(a, false);
    queries = queries + 1;
    console.log(`+  ${a}  insert at ${i}  steps ${steps - before}`);
  } else if (kind === "#") {
    const count = bound(a, true) - bound(a, false);
    queries = queries + 1;
    console.log(`#  ${a}  count ${count}  steps ${steps - before}`);
  } else if (kind === "[") {
    const b = Number(parts[2] ?? "0");
    const count = bound(b, true) - bound(a, false);
    queries = queries + 1;
    console.log(`[  ${a}  ${b}  in range ${count}  steps ${steps - before}`);
  } else if (kind === "~") {
    const value = xs.length === 0 ? 0 : nearest(a);
    queries = queries + 1;
    console.log(`~  ${a}  nearest ${value}  steps ${steps - before}`);
  }
}
console.log(`Queries:  ${queries}`);
console.log(`Steps:    ${steps}`);

