import * as fs from "fs";
const xs: readonly number[] = fs.readFileSync(0, "utf8")
  .trim()
  .split(/\s+/)
  .filter((s) => s !== "")
  .map(Number);
interface Run {
  readonly out: readonly number[];
  readonly cost: number;
}
function swap(ys: number[], i: number, j: number): void {
  const t = ys[i] ?? 0;
  ys[i] = ys[j] ?? 0;
  ys[j] = t;
}
function insertion(input: readonly number[]): Run {
  const ys = [...input];
  let cost = 0;
  const greater = (a: number, b: number): boolean => {
    cost = cost + 1;
    return a > b;
  };
  for (let i = 1; i < ys.length; i = i + 1) {
    const v = ys[i] ?? 0;
    let j = i - 1;
    while (j >= 0 && greater(ys[j] ?? 0, v)) {
      ys[j + 1] = ys[j] ?? 0;
      j = j - 1;
    }
    ys[j + 1] = v;
  }
  return { out: ys, cost };
}
function selection(input: readonly number[]): Run {
  const ys = [...input];
  let cost = 0;
  for (let i = 0; i < ys.length - 1; i = i + 1) {
    let min = i;
    for (let j = i + 1; j < ys.length; j = j + 1) {
      cost = cost + 1;
      if ((ys[j] ?? 0) < (ys[min] ?? 0)) {
        min = j;
      }
    }
    swap(ys, i, min);
  }
  return { out: ys, cost };
}
function mergeRun(input: readonly number[]): Run {
  let cost = 0;
  function merge(a: readonly number[], b: readonly number[]): readonly number[] {
    const out: number[] = [];
    let i = 0;
    let j = 0;
    while (i < a.length && j < b.length) {
      cost = cost + 1;
      if ((a[i] ?? 0) <= (b[j] ?? 0)) {
        out.push(a[i] ?? 0);
        i = i + 1;
      } else {
        out.push(b[j] ?? 0);
        j = j + 1;
      }
    }
    return [...out, ...a.slice(i), ...b.slice(j)];
  }
  function sort(ys: readonly number[]): readonly number[] {
    if (ys.length <= 1) {
      return ys;
    }
    const mid = Math.floor(ys.length / 2);
    return merge(sort(ys.slice(0, mid)), sort(ys.slice(mid)));
  }
  const out = sort(input);
  return { out, cost };
}
function quickRun(input: readonly number[]): Run {
  const ys = [...input];
  let cost = 0;
  function sort(lo: number, hi: number): void {
    if (lo >= hi) {
      return;
    }
    const pivot = ys[hi] ?? 0;
    let i = lo;
    for (let j = lo; j < hi; j = j + 1) {
      cost = cost + 1;
      if ((ys[j] ?? 0) < pivot) {
        swap(ys, i, j);
        i = i + 1;
      }
    }
    swap(ys, i, hi);
    sort(lo, i - 1);
    sort(i + 1, hi);
  }
  sort(0, ys.length - 1);
  return { out: ys, cost };
}
function countingRun(input: readonly number[]): Run {
  let cost = 0;
  let max = -1;
  for (const x of input) {
    max = Math.max(max, x);
    cost = cost + 1;
  }
  const counts: number[] = new Array(max + 1).fill(0);
  for (const x of input) {
    counts[x] = (counts[x] ?? 0) + 1;
    cost = cost + 1;
  }
  const out: number[] = [];
  for (let v = 0; v <= max; v = v + 1) {
    cost = cost + 1;
    for (let c = 0; c < (counts[v] ?? 0); c = c + 1) {
      out.push(v);
    }
  }
  return { out, cost };
}
function row(label: string, text: string): string {
  return `${(label + ":").padEnd(11)}${text}`;
}
const want = [...xs].sort((a, b) => a - b).join(",");
const compared: readonly [string, Run][] = [
  ["Insertion", insertion(xs)],
  ["Selection", selection(xs)],
  ["Merge", mergeRun(xs)],
  ["Quick", quickRun(xs)],
];
const counted = countingRun(xs);
console.log(row("Sorted", xs.length === 0 ? "(empty)" : [...xs].sort((a, b) => a - b).join(" ")));
for (const [label, run] of compared) {
  console.log(row(label, `cmp ${String(run.cost).padStart(3)}`));
}
console.log(row("Counting", `ops ${String(counted.cost).padStart(3)}`));
const agree = [...compared.map(([, run]) => run), counted].every((run) => run.out.join(",") === want);
console.log(row("Agree", agree ? "yes" : "no"));
let fewest = "insertion";
let fewestCost = Number.MAX_SAFE_INTEGER;
for (const [label, run] of compared) {
  if (run.cost < fewestCost) {
    fewest = label.toLowerCase();
    fewestCost = run.cost;
  }
}
console.log(row("Fewest", fewest));

