import * as fs from "fs";
interface Row {
  readonly name: string;
  readonly score: number;
  readonly at: number;
}
const rows: readonly Row[] = fs.readFileSync(0, "utf8")
  .split("\n")
  .map((l) => l.trim())
  .filter((l) => l !== "")
  .map((l, at) => {
    const [name, score] = l.split(/\s+/);
    return { name: name ?? "", score: Number(score ?? "0"), at };
  });
function pick(rs: readonly Row[], i: number): Row {
  return rs[i] ?? { name: "", score: 0, at: 0 };
}
function insertion(input: readonly Row[]): readonly Row[] {
  const rs = [...input];
  for (let i = 1; i < rs.length; i = i + 1) {
    const v = pick(rs, i);
    let j = i - 1;
    while (j >= 0 && pick(rs, j).score > v.score) {
      rs[j + 1] = pick(rs, j);
      j = j - 1;
    }
    rs[j + 1] = v;
  }
  return rs;
}
function mergeSort(rs: readonly Row[]): readonly Row[] {
  if (rs.length <= 1) {
    return rs;
  }
  const mid = Math.floor(rs.length / 2);
  const a = mergeSort(rs.slice(0, mid));
  const b = mergeSort(rs.slice(mid));
  const out: Row[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (pick(a, i).score <= pick(b, j).score) {
      out.push(pick(a, i));
      i = i + 1;
    } else {
      out.push(pick(b, j));
      j = j + 1;
    }
  }
  return [...out, ...a.slice(i), ...b.slice(j)];
}
function quick(input: readonly Row[]): readonly Row[] {
  const rs = [...input];
  function swap(i: number, j: number): void {
    const t = pick(rs, i);
    rs[i] = pick(rs, j);
    rs[j] = t;
  }
  function sort(lo: number, hi: number): void {
    if (lo >= hi) {
      return;
    }
    const pivot = pick(rs, hi).score;
    let i = lo;
    for (let j = lo; j < hi; j = j + 1) {
      if (pick(rs, j).score < pivot) {
        swap(i, j);
        i = i + 1;
      }
    }
    swap(i, hi);
    sort(lo, i - 1);
    sort(i + 1, hi);
  }
