interface T {
  readonly value: number;
  readonly left: T | null;
  readonly right: T | null;
}
function leaf(value: number): T {
  return { value, left: null, right: null };
}
const tree: T = {
  value: 1,
  left: { value: 2, left: leaf(4), right: leaf(5) },
  right: leaf(3),
};
function pre(t: T | null, out: number[]): void {
  if (t === null) {
    return;
  }
  out.push(t.value);
  pre(t.left, out);
  pre(t.right, out);
}
const viaCalls: number[] = [];
pre(tree, viaCalls);
const viaStack: number[] = [];
const stack: T[] = [tree];
while (stack.length > 0) {
  const t = stack.pop();
  if (t === undefined) {
    continue;
  }
  viaStack.push(t.value);
  if (t.right !== null) {
    stack.push(t.right);
  }
  if (t.left !== null) {
    stack.push(t.left);
  }
}
console.log(`${viaCalls.join(",")} ${viaStack.join(",")} same=${viaCalls.join(",") === viaStack.join(",")}`);

