// Supplied by the checker. Equal<X, Y> is true only when X and Y are the SAME
// type, not merely assignable to each other.
type Equal<X, Y> =
  (<T>() => T extends X ? 1 : 2) extends (<T>() => T extends Y ? 1 : 2) ? true : false;
type Expect<T extends true> = T;

const _s = permutations(["x", "y"]);
type _1 = Expect<Equal<typeof _s, string[][]>>;
const _n = permutations([1, 2]);
type _2 = Expect<Equal<typeof _n, number[][]>>;

exercises.starter:
function permutations(xs: any): any {
  if (xs.length <= 1) {
    return [[...xs]];
  }
  const out: any = [];
  for (let i = 0; i < xs.length; i = i + 1) {
    const rest = [...xs.slice(0, i), ...xs.slice(i + 1)];
    for (const p of permutations(rest)) {
      out.push([xs[i], ...p]);
    }
  }
  return out;
}
console.log(permutations(["a", "b", "c"]).map((p: any) => p.join("")).join(" "));

exercises.solution:
function permutations<T>(xs: readonly T[]): T[][] {
  if (xs.length <= 1) {
    return [[...xs]];
  }
  const out: T[][] = [];
  for (let i = 0; i < xs.length; i = i + 1) {
    const first = xs[i];
    if (first === undefined) {
      continue;
    }
    const rest = [...xs.slice(0, i), ...xs.slice(i + 1)];
    for (const p of permutations(rest)) {
      out.push([first, ...p]);
    }
  }
  return out;
}
console.log(permutations(["a", "b", "c"]).map((p) => p.join("")).join(" "));

