function queens(n: number): number {
  const cols = new Set<number>();
  const d1 = new Set<number>();
  const d2 = new Set<number>();
  let count = 0;
  function place(r: number): void {
    if (r === n) {
      count = count + 1;
      return;
    }
    for (let c = 0; c < n; c = c + 1) {
____
      cols.add(c);
      d1.add(r + c);
      d2.add(r - c);
      place(r + 1);
      cols.delete(c);
      d1.delete(r + c);
      d2.delete(r - c);
    }
  }
  place(0);
  return count;
}
for (const n of [4, 5, 6]) {
  console.log(`n=${n} solutions=${queens(n)}`);
}

