let naiveCalls = 0;
function ways(n: number): number {
  naiveCalls = naiveCalls + 1;
  return n <= 1 ? 1 : ways(n - 1) + ways(n - 2);
}
const memo = new Map<number, number>();
let memoCalls = 0;
function fastWays(n: number): number {
  memoCalls = memoCalls + 1;
  if (n <= 1) {
    return 1;
  }
  const known = memo.get(n);
  if (known !== undefined) {
    return known;
  }
  const result = fastWays(n - 1) + fastWays(n - 2);
____
  return result;
}
console.log(`ways=${ways(20)} naive=${naiveCalls} fast=${fastWays(20)} memo=${memoCalls}`);

