import * as fs from "fs";
const lines = fs.readFileSync(0, "utf8").split("\n");
const xs: readonly number[] = (lines[0] ?? "")
  .trim()
  .split(/\s+/)
  .filter((s) => s !== "")
  .map(Number)
  .sort((a, b) => a - b);
const target = Number((lines[1] ?? "").trim() || "0");
const path: number[] = [];
const found: string[] = [];
let visited = 0;
function go(start: number, remaining: number): void {
  visited = visited + 1;
  if (remaining === 0) {
    found.push(path.join("+"));
    return;
  }
  for (let j = start; j < xs.length; j = j + 1) {
    const x = xs[j] ?? 0;
    if (j > start && x === (xs[j - 1] ?? 0)) {
      continue;
    }
    if (x > remaining) {
      break;
    }
    path.push(x);
    go(j + 1, remaining - x);
    path.pop();
  }
}
if (xs.length > 0 && target > 0) {
  go(0, target);
}
for (const f of found) {
  console.log(f);
}
if (found.length === 0) {
  console.log("none");
}
console.log(`found ${found.length}  visited ${visited}`);

