import * as fs from "fs";
const n = Number(fs.readFileSync(0, "utf8").trim() || "0");
const cols = new Set<number>();
const d1 = new Set<number>();
const d2 = new Set<number>();
const queenAt: number[] = [];
const boards: (readonly number[])[] = [];
let solutions = 0;
let visited = 0;
function place(r: number): void {
  visited = visited + 1;
  if (r === n) {
    solutions = solutions + 1;
    if (boards.length === 0) {
      boards.push([...queenAt]);
    }
    return;
  }
  for (let c = 0; c < n; c = c + 1) {
    if (cols.has(c) || d1.has(r + c) || d2.has(r - c)) {
      continue;
    }
    cols.add(c);
    d1.add(r + c);
    d2.add(r - c);
    queenAt.push(c);
    place(r + 1);
    queenAt.pop();
    cols.delete(c);
    d1.delete(r + c);
    d2.delete(r - c);
  }
}
if (n > 0) {
  place(0);
}
const first = boards[0];
if (first === undefined) {
  console.log("no solution");
} else {
  for (const c of first) {
