  .trim()
  .split(/\s+/)
  .filter((s) => s !== "")
  .map(Number)
  .sort((a, b) => a - b);
const amount = Number((lines[1] ?? "").trim() || "0");
function row(label: string, text: string): string {
  return `${(label + ":").padEnd(11)}${text}`;
}
function describe(used: readonly number[]): string {
  const parts = [...used].sort((a, b) => b - a);
  return `${parts.length}  ${parts.length === 0 ? "-" : parts.join("+")}`;
}
const fewest: number[] = [0];
const choice: number[] = [0];
for (let a = 1; a <= amount; a = a + 1) {
  let best = Infinity;
  let pick = 0;
  for (const c of coins) {
    if (c <= a && (fewest[a - c] ?? Infinity) + 1 < best) {
      best = (fewest[a - c] ?? Infinity) + 1;
      pick = c;
    }
  }
  fewest.push(best);
  choice.push(pick);
}
if ((fewest[amount] ?? Infinity) === Infinity) {
  console.log(row("Fewest", "none"));
} else {
  const used: number[] = [];
  let a = amount;
  while (a > 0) {
    const c = choice[a] ?? 0;
    used.push(c);
    a = a - c;
  }
  console.log(row("Fewest", describe(used)));
}
const greedy: number[] = [];
let left = amount;
for (const c of [...coins].reverse()) {
  while (c > 0 && left >= c) {
    greedy.push(c);
    left = left - c;
  }
}
console.log(row("Greedy", left === 0 ? describe(greedy) : "none"));
const ways: number[] = new Array<number>(amount + 1).fill(0);
ways[0] = 1;
for (const c of coins) {
  for (let a = c; a <= amount; a = a + 1) {
    ways[a] = (ways[a] ?? 0) + (ways[a - c] ?? 0);
  }
}
