const b = (lines[1] ?? "").trim();
function makeGrid(rows: number, cols: number): number[][] {
  return Array.from({ length: rows }, () => new Array<number>(cols).fill(0));
}
function at(g: readonly (readonly number[])[], r: number, c: number): number {
  return g[r]?.[c] ?? 0;
}
function put(g: number[][], r: number, c: number, v: number): void {
  const row = g[r];
  if (row !== undefined) {
    row[c] = v;
  }
}
const dp = makeGrid(a.length + 1, b.length + 1);
for (let i = 0; i <= a.length; i = i + 1) {
  put(dp, i, 0, i);
}
for (let j = 0; j <= b.length; j = j + 1) {
  put(dp, 0, j, j);
}
for (let i = 1; i <= a.length; i = i + 1) {
  for (let j = 1; j <= b.length; j = j + 1) {
    if (a.charAt(i - 1) === b.charAt(j - 1)) {
      put(dp, i, j, at(dp, i - 1, j - 1));
    } else {
      put(dp, i, j, 1 + Math.min(at(dp, i - 1, j - 1), at(dp, i - 1, j), at(dp, i, j - 1)));
    }
  }
}
const edits: string[] = [];
let i = a.length;
let j = b.length;
while (i > 0 || j > 0) {
  const here = at(dp, i, j);
  if (i > 0 && j > 0 && a.charAt(i - 1) === b.charAt(j - 1) && here === at(dp, i - 1, j - 1)) {
    i = i - 1;
    j = j - 1;
  } else if (i > 0 && j > 0 && here === at(dp, i - 1, j - 1) + 1) {
    edits.push(`sub ${a.charAt(i - 1)}>${b.charAt(j - 1)}`);
    i = i - 1;
    j = j - 1;
  } else if (i > 0 && here === at(dp, i - 1, j) + 1) {
    edits.push(`del ${a.charAt(i - 1)}`);
    i = i - 1;
  } else {
    edits.push(`ins ${b.charAt(j - 1)}`);
    j = j - 1;
  }
}
console.log(`distance ${at(dp, a.length, b.length)}`);
for (const e of edits.reverse()) {
