import * as fs from "fs";
const grid: readonly string[] = fs.readFileSync(0, "utf8").trim().split("\n").map((l) => l.trim());
const R = grid.length;
const C = (grid[0] ?? "").length;
function cell(r: number, c: number): string {
  if (r < 0 || r >= R || c < 0 || c >= C) {
    return "";
  }
  return (grid[r] ?? "").charAt(c);
}
const DIRS: readonly (readonly [number, number])[] = [[-1, 0], [1, 0], [0, -1], [0, 1]];
const seen = new Array<boolean>(R * C).fill(false);
function isLand(id: number): boolean {
  return id >= 0 && id < R * C && cell(Math.floor(id / C), id % C) === "#";
}
let islands = 0;
for (let start = 0; start < R * C; start = start + 1) {
  if (!isLand(start) || seen[start]) {
    continue;
  }
  islands = islands + 1;
  seen[start] = true;
  const stack = [start];
  while (stack.length > 0) {
    const id = stack.pop() ?? 0;
    for (const next of [id - C, id + C, id - 1, id + 1]) {
      if (isLand(next) && !seen[next]) {
        seen[next] = true;
        stack.push(next);
      }
    }
  }
}
console.log(islands);

