exercise.solution:
import * as fs from "fs";
const maze: readonly string[] = fs.readFileSync(0, "utf8").trim().split("\n").map((l) => l.trim());
const R = maze.length;
const C = (maze[0] ?? "").length;
function at(r: number, c: number): string {
  if (r < 0 || r >= R || c < 0 || c >= C) {
    return "#";
  }
  return (maze[r] ?? "").charAt(c);
}
let start: readonly [number, number] = [0, 0];
for (let r = 0; r < R; r = r + 1) {
  for (let c = 0; c < C; c = c + 1) {
    if (at(r, c) === "S") {
      start = [r, c];
    }
  }
}
const DIRS: readonly (readonly [number, number])[] = [[-1, 0], [1, 0], [0, -1], [0, 1]];
const parent = new Map<string, string>();
const seen = new Set<string>([`${start[0]},${start[1]}`]);
const queue: (readonly [number, number])[] = [start];
let explored = 0;
let exit: readonly [number, number] | null = null;
for (let head = 0; head < queue.length; head = head + 1) {
  const [r, c] = queue[head] ?? [0, 0];
  if (at(r, c) === "E") {
    exit = [r, c];
    break;
  }
  explored = explored + 1;
  for (const [dr, dc] of DIRS) {
    const nr = r + dr;
    const nc = c + dc;
    const key = `${nr},${nc}`;
    if (at(nr, nc) !== "#" && !seen.has(key)) {
      seen.add(key);
      parent.set(key, `${r},${c}`);
      queue.push([nr, nc]);
    }
  }
}
const out = maze.map((row) => [...row]);
if (exit === null) {
  console.log(maze.join("\n"));
  console.log(`no way out  explored ${explored}`);
} else {
  let steps = 0;
  let key = parent.get(`${exit[0]},${exit[1]}`);
  steps = steps + 1;
  while (key !== undefined && key !== `${start[0]},${start[1]}`) {
    const [r, c] = key.split(",").map(Number);
    const row = out[r ?? 0];
    if (row !== undefined) {
      row[c ?? 0] = "*";
    }
    steps = steps + 1;
    key = parent.get(key);
  }
  console.log(out.map((row) => row.join("")).join("\n"));
  console.log(`steps ${steps}  explored ${explored}`);
}

