import * as fs from "fs";
type DeepPartial<T> = T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } : T;
type DeepReadonly<T> = T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } : T;
function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
interface Config {
  name: string;
  db: { host: string; port: number };
  debug: boolean;
}
const DEFAULTS: Config = { name: "app", db: { host: "localhost", port: 5432 }, debug: false };
function mergeDeep<T>(base: T, patch: DeepPartial<T>): T {
  if (!isRecord(base) || !isRecord(patch)) {
    return (patch === undefined ? base : patch) as T;
  }
  const out: Record<string, unknown> = { ...base };
  for (const [k, v] of Object.entries(patch)) {
    if (v !== undefined) {
      out[k] = mergeDeep<unknown>(base[k], v);
    }
  }
  return out as T;
}
function deepFreeze<T>(value: T): DeepReadonly<T> {
  if (isRecord(value)) {
    for (const v of Object.values(value)) {
      deepFreeze(v);
    }
    Object.freeze(value);
  }
  return value as DeepReadonly<T>;
}
function configure(patch: DeepPartial<Config>): DeepReadonly<Config> {
  return deepFreeze(mergeDeep(DEFAULTS, patch));
}
const cfg = configure(JSON.parse(fs.readFileSync(0, "utf8")) as DeepPartial<Config>);
console.log(JSON.stringify(cfg));
console.log(`frozen ${Object.isFrozen(cfg)} ${Object.isFrozen(cfg.db)}`);

