import * as fs from "fs";
type ParamNames<P extends string> =
  P extends `${string}:${infer Name}/${infer Rest}` ? Name | ParamNames<`/${Rest}`>
  : P extends `${string}:${infer Name}` ? Name
  : never;
type Params<P extends string> = { [K in ParamNames<P>]: string };
interface Route {
  readonly pattern: string;
  readonly handle: (params: Record<string, string>) => string;
}
class Router {
  private readonly routes: Route[] = [];
  add<P extends string>(pattern: P, handler: (params: Params<P>) => string): this {
    this.routes.push({ pattern, handle: handler as (params: Record<string, string>) => string });
    return this;
  }
  resolve(path: string): string {
    const parts = path.split("/").filter((s) => s !== "");
    for (const r of this.routes) {
      const want = r.pattern.split("/").filter((s) => s !== "");
      if (want.length !== parts.length) {
        continue;
      }
      const params: Record<string, string> = {};
      let ok = true;
      want.forEach((w, i) => {
        const got = parts[i] ?? "";
        if (w.startsWith(":")) {
          params[w.slice(1)] = got;
        } else if (w !== got) {
          ok = false;
        }
      });
      if (ok) {
        return r.handle(params);
      }
    }
    return `404 ${path}`;
  }
}
const router = new Router()
  .add("/health", () => "ok")
  .add("/users/:id", (p) => `user ${p.id}`)
  .add("/users/:id/posts/:postId", (p) => `post ${p.postId} by ${p.id}`);
const lines = fs.readFileSync(0, "utf8").split("\n").map((l) => l.trim()).filter((l) => l !== "");
for (const line of lines) {
  console.log(router.resolve(line));
}

