type Listener<A extends unknown[]> = (...args: A) => void;
class Emitter<E extends Record<string, unknown[]>> {
  private readonly listeners: { [K in keyof E]?: Listener<E[K]>[] } = {};
  on<K extends keyof E>(event: K, listener: Listener<E[K]>): this {
    (this.listeners[event] ??= []).push(listener);
    return this;
  }
  off<K extends keyof E>(event: K, listener: Listener<E[K]>): this {
    this.listeners[event] = (this.listeners[event] ?? []).filter((l) => l !== listener);
    return this;
  }
  once<K extends keyof E>(event: K, listener: Listener<E[K]>): this {
    const wrapper: Listener<E[K]> = (...args) => {
      this.off(event, wrapper);
      listener(...args);
    };
    return this.on(event, wrapper);
  }
  emit<K extends keyof E>(event: K, ...args: E[K]): number {
    const ls = [...(this.listeners[event] ?? [])];
    for (const l of ls) {
      l(...args);
    }
    return ls.length;
  }
}
type Events = { tick: [n: number] };
const em = new Emitter<Events>();
const always = (n: number): void => console.log(`always ${n}`);
em.on("tick", always).once("tick", (n) => console.log(`once ${n}`));
em.emit("tick", 1);
em.emit("tick", 2);
em.off("tick", always);
console.log(`left ${em.emit("tick", 3)}`);

