function hasPairBrute(nums: number[], target: number): boolean {
  for (let i = 0; i < nums.length; i = i + 1) {
    for (let j = i + 1; j < nums.length; j = j + 1) {
      if ((nums[i] ?? 0) + (nums[j] ?? 0) === target) {
        return true;
      }
