exercises.solution:
function twoSum(nums: number[], target: number): number[] {
  const at = new Map<number, number>();
  for (let j = 0; j < nums.length; j = j + 1) {
    const x = nums[j] ?? 0;
    const i = at.get(target - x);
    if (i !== undefined) {
      return [i, j];
    }
    if (!at.has(x)) {
      at.set(x, j);
    }
  }
  return [];
}

