exercises.solution:
function longestConsecutive(nums: number[]): number {
  const set = new Set(nums);
  let best = 0;
  for (const x of set) {
    if (set.has(x - 1)) {
      continue;
    }
    let len = 1;
    while (set.has(x + len)) {
      len = len + 1;
    }
    best = Math.max(best, len);
  }
  return best;
}

