exercises.solution:
function productExceptSelf(nums: number[]): number[] {
  const out = new Array<number>(nums.length).fill(1);
  let left = 1;
  for (let i = 0; i < nums.length; i = i + 1) {
    out[i] = left;
    left = left * (nums[i] ?? 0);
  }
  let right = 1;
  for (let i = nums.length - 1; i >= 0; i = i - 1) {
    out[i] = (out[i] ?? 1) * right;
    right = right * (nums[i] ?? 0);
  }
  return out;
}

