exercises.solution:
function searchRotated(nums: number[], target: number): number {
  let lo = 0;
  let hi = nums.length - 1;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    const m = nums[mid] ?? 0;
    if (m === target) {
      return mid;
    }
    const l = nums[lo] ?? 0;
    const h = nums[hi] ?? 0;
    if (l <= m) {
      if (l <= target && target < m) {
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    } else if (m < target && target <= h) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return -1;
}

