function maxArea(heights: number[]): number {
  let lo = 0;
  let hi = heights.length - 1;
  let best = 0;
  while (lo < hi) {
    const a = heights[lo] ?? 0;
    const b = heights[hi] ?? 0;
    best = Math.max(best, (hi - lo) * Math.min(a, b));
    if (a < b) {
      lo = lo + 1;
    } else {
      hi = hi - 1;
    }
  }
  return best;
}

