exercises.solution:
function minSubarrayLen(target: number, nums: number[]): number {
  let start = 0;
  let sum = 0;
  let best = Infinity;
  for (let end = 0; end < nums.length; end = end + 1) {
    sum = sum + (nums[end] ?? 0);
    while (sum >= target) {
      best = Math.min(best, end - start + 1);
      sum = sum - (nums[start] ?? 0);
      start = start + 1;
    }
  }
  return best === Infinity ? 0 : best;
}

