exercises.solution:
function numIslands(grid: string[]): number {
  const R = grid.length;
  const C = (grid[0] ?? "").length;
  const seen = new Set<string>();
  let count = 0;
  for (let r = 0; r < R; r = r + 1) {
    for (let c = 0; c < C; c = c + 1) {
      if ((grid[r] ?? "").charAt(c) !== "1" || seen.has(`${r},${c}`)) {
        continue;
      }
      count = count + 1;
      seen.add(`${r},${c}`);
      const stack: [number, number][] = [[r, c]];
      while (stack.length > 0) {
        const top = stack.pop();
        if (top === undefined) {
          continue;
        }
        const [cr, cc] = top;
        const next: [number, number][] = [[cr - 1, cc], [cr + 1, cc], [cr, cc - 1], [cr, cc + 1]];
        for (const [nr, nc] of next) {
          if (nr < 0 || nr >= R || nc < 0 || nc >= C) {
            continue;
          }
          if ((grid[nr] ?? "").charAt(nc) === "1" && !seen.has(`${nr},${nc}`)) {
            seen.add(`${nr},${nc}`);
            stack.push([nr, nc]);
          }
        }
      }
    }
  }
  return count;
}

