exercises.solution:
function shortestPath(grid: string[]): number {
  const R = grid.length;
  const C = (grid[0] ?? "").length;
  const open = (r: number, c: number): boolean =>
    r >= 0 && r < R && c >= 0 && c < C && (grid[r] ?? "").charAt(c) === "0";
  if (!open(0, 0)) {
    return -1;
  }
  const dist = new Map<string, number>([["0,0", 0]]);
  const queue: [number, number][] = [[0, 0]];
  for (let head = 0; head < queue.length; head = head + 1) {
    const [r, c] = queue[head] ?? [0, 0];
    const d = dist.get(`${r},${c}`) ?? 0;
    if (r === R - 1 && c === C - 1) {
      return d;
    }
    const next: [number, number][] = [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]];
    for (const [nr, nc] of next) {
      if (open(nr, nc) && !dist.has(`${nr},${nc}`)) {
        dist.set(`${nr},${nc}`, d + 1);
        queue.push([nr, nc]);
      }
    }
  }
  return -1;
}

