exercises.solution:
function canFinish(n: number, pairs: number[]): boolean {
  const adj: number[][] = Array.from({ length: n }, (): number[] => []);
  const indegree = new Array<number>(n).fill(0);
  for (let i = 0; i + 1 < pairs.length; i = i + 2) {
    const a = pairs[i] ?? 0;
    const b = pairs[i + 1] ?? 0;
    adj[b]?.push(a);
    indegree[a] = (indegree[a] ?? 0) + 1;
  }
  const queue: number[] = [];
  for (let u = 0; u < n; u = u + 1) {
    if (indegree[u] === 0) {
      queue.push(u);
    }
  }
  for (let head = 0; head < queue.length; head = head + 1) {
    for (const v of adj[queue[head] ?? 0] ?? []) {
      indegree[v] = (indegree[v] ?? 0) - 1;
      if (indegree[v] === 0) {
        queue.push(v);
      }
    }
  }
  return queue.length === n;
}

