exercises.solution:
function countComponents(n: number, edges: number[]): number {
  const adj: number[][] = Array.from({ length: n }, (): number[] => []);
  for (let i = 0; i + 1 < edges.length; i = i + 2) {
    const u = edges[i] ?? 0;
    const v = edges[i + 1] ?? 0;
    adj[u]?.push(v);
    adj[v]?.push(u);
  }
  const seen = new Array<boolean>(n).fill(false);
  let count = 0;
  for (let s = 0; s < n; s = s + 1) {
    if (seen[s]) {
      continue;
    }
    count = count + 1;
    seen[s] = true;
    const stack = [s];
    while (stack.length > 0) {
      const u = stack.pop() ?? 0;
      for (const v of adj[u] ?? []) {
        if (!seen[v]) {
          seen[v] = true;
          stack.push(v);
        }
      }
    }
  }
  return count;
}

