exercises.solution:
function coinChange(coins: number[], amount: number): number {
  const dp: number[] = [0];
  for (let a = 1; a <= amount; a = a + 1) {
    let best = Infinity;
    for (const c of coins) {
      if (c <= a) {
        best = Math.min(best, (dp[a - c] ?? Infinity) + 1);
      }
    }
    dp.push(best);
  }
  const answer = dp[amount] ?? Infinity;
  return answer === Infinity ? -1 : answer;
}

