exercises.solution:
function lcsLength(a: string, b: string): number {
  const dp: number[][] = Array.from({ length: a.length + 1 }, (): number[] => new Array<number>(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i = i + 1) {
    const row = dp[i] ?? [];
    const up = dp[i - 1] ?? [];
    for (let j = 1; j <= b.length; j = j + 1) {
      row[j] = a.charAt(i - 1) === b.charAt(j - 1)
        ? (up[j - 1] ?? 0) + 1
        : Math.max(up[j] ?? 0, row[j - 1] ?? 0);
    }
  }
  return dp[a.length]?.[b.length] ?? 0;
}

