function trap(heights: number[]): number {
  let lo = 0;
  let hi = heights.length - 1;
  let leftMax = 0;
  let rightMax = 0;
  let water = 0;
  while (lo < hi) {
    const a = heights[lo] ?? 0;
    const b = heights[hi] ?? 0;
    if (a < b) {
      leftMax = Math.max(leftMax, a);
      water = water + (leftMax - a);
      lo = lo + 1;
    } else {
      rightMax = Math.max(rightMax, b);
      water = water + (rightMax - b);
      hi = hi - 1;
    }
  }
  return water;
}

