// What a strong answer sounds like, written down, for round 1's longestConsecutive.
//
// 1. Clarify: "Can nums be empty? (Then 0.) Duplicates? (Count once.) Negative values? (Fine.)
//    Is O(n log n) acceptable, or do you want O(n)?" — the prompt said O(n).
// 2. Examples: [100, 4, 200, 1, 3, 2] -> 4 (1-2-3-4). Edge: [] -> 0. [5] -> 1.
// 3. Brute force: sort, then scan for runs. O(n log n) time — correct, and my floor.
// 4. Optimise: "Consecutive" and "seen before" — a Set (week 19). Count a run only from its
//    START (x - 1 absent), so each run is walked once: O(n).
// 5. Code:
function longestConsecutive(nums: readonly number[]): number {
  const set = new Set(nums);
  let best = 0;
  for (const x of set) {
    if (set.has(x - 1)) {
      continue;              // not the start of a run
    }
    let len = 1;
    while (set.has(x + len)) {
      len = len + 1;
    }
    best = Math.max(best, len);
  }
  return best;
}
// 6. Walkthrough: 100 starts a run of 1; 4 is skipped (3 present); 1 starts 1,2,3,4 -> 4. [] -> 0.
// 7. Complexity: O(n) time — every value is visited at most twice, once by the outer loop and
//    at most once by some while loop. O(n) space for the Set.
console.log(longestConsecutive([100, 4, 200, 1, 3, 2]));

