function medianOfTwo(a: number[], b: number[]): number {
  const merged: number[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length || j < b.length) {
    const x = a[i];
    const y = b[j];
    if (y === undefined || (x !== undefined && x <= y)) {
      merged.push(x ?? 0);
      i = i + 1;
    } else {
      merged.push(y);
      j = j + 1;
    }
  }
  const n = merged.length;
  if (n === 0) {
    return 0;
  }
  const mid = Math.floor(n / 2);
  return n % 2 === 1 ? merged[mid] ?? 0 : ((merged[mid - 1] ?? 0) + (merged[mid] ?? 0)) / 2;
}
